157:type encodedRealtimeLaneGroup struct {
158:	Key     string
159:	Packets []realtime.EncodedRealtimeLanePacket
160:}
161:
162:func groupEncodedRealtimeLanePackets(packets []realtime.EncodedRealtimeLanePacket) []encodedRealtimeLaneGroup {
163:	groups := make([]encodedRealtimeLaneGroup, 0, len(packets))
164:	indexes := make(map[string]int, len(packets))
165:	for _, packet := range packets {
166:		key := realtimeSendGroupKey(packet.Candidate)
167:		if index, ok := indexes[key]; ok {
168:			groups[index].Packets = append(groups[index].Packets, packet)
169:			continue
170:		}
171:		indexes[key] = len(groups)
172:		groups = append(groups, encodedRealtimeLaneGroup{Key: key, Packets: []realtime.EncodedRealtimeLanePacket{packet}})
173:	}
174:	return groups
175:}
176:
177:func realtimeSendGroupKey(candidate realtime.RealtimeLaneCandidate) string {
178:	switch candidate.Lane() {
179:	case realtime.LaneWorld, realtime.LaneShipsLifecycle, realtime.LaneAsteroidsLifecycle, realtime.LaneBulletsLifecycle:
180:		return "world.reliable"
181:	default:
182:		return string(candidate.Lane())
183:	}
184:}
