186:func preflightRealtimeSendGroup(session *webSocketSession, transport *WebRTCTransport, group encodedRealtimeLaneGroup, context SessionContext, matchID string) (bool, bool) {
187:	reservedBytesByLane := make(map[string]uint64)
188:	for _, encoded := range group.Packets {
189:		candidate := encoded.Candidate
190:		if len(encoded.Encoded) == 0 {
191:			continue
192:		}
193:		lane := string(candidate.Lane())
194:		if candidate.Lane() == realtime.LaneControl {
195:			logging.Emit(observability.Request{
196:				Event: observability.EventNamePacketRouteFailed,
197:				Context: observability.Context{
198:					TraceID:    session.connectionTraceID,
199:					SessionID:  session.sessionID,
200:					RoomID:     context.RoomID,
201:					PlayerID:   context.GamePlayerID,
202:					MatchID:    matchID,
203:					PacketType: candidate.PacketFamily(),
204:				},
205:				Fields: observability.Fields{
206:					"error_code":   "control_lane_wrong_transport",
207:					"failure_mode": "control_lane_wrong_transport",
208:					"lane":         lane,
209:					"transport":    "webrtc",
210:				},
211:			})
212:			return false, false
213:		}
214:		channelLabel, ok := webRTCChannelLabelForLane(lane)
215:		if !ok {
216:			return false, false
217:		}
218:		bufferedBytes, ok := transport.BufferedAmountForLane(lane)
219:		if !ok {
220:			return false, false
221:		}
222:		reservedBytes := reservedBytesByLane[lane]
223:		payloadBytes := uint64(len(encoded.Encoded))
224:		if bufferedBytes >= webRTCMaxBufferedAmountBytes || reservedBytes+payloadBytes > webRTCMaxBufferedAmountBytes-bufferedBytes {
225:			logRealtimeBackpressure(session, transport, candidate, lane, channelLabel, context, matchID, reservedBytes)
226:			return true, true
227:		}
228:		reservedBytesByLane[lane] = reservedBytes + payloadBytes
229:	}
230:	return false, true
231:}
232:
233:func logRealtimeBackpressure(session *webSocketSession, transport *WebRTCTransport, candidate realtime.RealtimeLaneCandidate, lane string, channelLabel string, context SessionContext, matchID string, reservedBytes uint64) {
234:	if !session.shouldLogWebRTCBackpressure(lane) {
235:		return
236:	}
237:	bufferedBytes, _ := transport.BufferedAmountForLane(lane)
238:	logging.Emit(observability.Request{
239:		Event: observability.EventNamePacketRouteFailed,
240:		Context: observability.Context{
241:			TraceID:    session.connectionTraceID,
242:			SessionID:  session.sessionID,
243:			RoomID:     context.RoomID,
244:			PlayerID:   context.GamePlayerID,
245:			MatchID:    matchID,
246:			PacketType: candidate.PacketFamily(),
247:		},
248:		Fields: observability.Fields{
249:			"error_code":     "webrtc_channel_backpressure",
250:			"failure_mode":   "webrtc_channel_backpressure",
251:			"lane":           lane,
252:			"transport":      "webrtc",
253:			"channel":        channelLabel,
254:			"buffered_bytes": bufferedBytes,
255:			"reserved_bytes": reservedBytes,
256:		},
257:	})
258:}
259:
260:func resetRealtimeStateForContext(session *webSocketSession, context SessionContext, matchID string) {
261:	if session == nil || context.Room == nil || context.GamePlayerID == "" {
262:		return
263:	}
264:	if !session.realtimeState.IdentityMatches(context.GamePlayerID, matchID) {
265:		session.realtimeState = realtime.NewRealtimeSessionState(context.GamePlayerID, matchID)
266:	}
267:}
268:
269:func drainActiveEventBatchAfterWrite(gameInstance *game.Game, playerID string, eventIDs []string) []game.PendingPresentationEvent {
270:	if gameInstance == nil || len(eventIDs) == 0 {
271:		return nil
272:	}
273:	return gameInstance.DrainPendingPresentationEvents(playerID, eventIDs...)
274:}

