330:func (p *WebRTCTransport) createNegotiatedChannels() error {
331:	negotiated := true
332:	for _, spec := range webRTCChannelSpecs() {
333:		ordered := spec.Ordered
334:		channelID := spec.ID
335:		channel, err := p.peer.CreateDataChannel(spec.Label, &webrtc.DataChannelInit{
336:			Ordered:        &ordered,
337:			Negotiated:     &negotiated,
338:			ID:             &channelID,
339:			MaxRetransmits: spec.MaxRetransmits,
340:		})
341:		if err != nil {
342:			return err
343:		}
344:		lane := spec.Lane
345:		p.mu.Lock()
346:		p.channels[lane] = channel
347:		p.readyChannels[lane] = false
348:		p.mu.Unlock()
349:		channel.OnOpen(func() {
350:			p.mu.Lock()
351:			p.readyChannels[lane] = true
352:			wasReady := p.ready
353:			p.ready = p.allRequiredChannelsReadyLocked()
354:			readyChanged := !wasReady && p.ready
355:			onReady := p.hooks.OnReady
356:			p.mu.Unlock()
357:			if readyChanged && onReady != nil {
358:				onReady()
359:			}
360:		})
361:		channel.OnClose(func() {
362:			p.handleChannelClosed(lane)
363:		})
364:		channel.OnMessage(func(msg webrtc.DataChannelMessage) {
365:			_ = p.handleChannelMessage(lane, msg.Data)
366:		})
367:	}
368:	return nil
369:}
